export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A row of the `jobs` table, with the columns selected by JOB_COLUMNS. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
}

const JOB_COLUMNS = 'seq, id, status, input, steps, fail_attempts, attempts, completed, result_output, error, created_at, updated_at';

export function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed, total: r.steps },
    result: r.result_output === null ? null : { output: r.result_output },
    error: r.error,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | null;
}

export function insertJob(db: DatabaseSync, job: NewJob): Job {
  const id = randomUUID();
  const now = new Date();
  const iso = now.toISOString();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, available_at, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)`,
  ).run(id, job.input, job.steps, job.failAttempts, job.idempotencyKey, now.getTime(), iso, iso);
  return getJob(db, id)!;
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as JobRow | undefined;
  return row && toJob(row);
}

/** Returns the raw row for a job created with this idempotency key, with its idempotency key. */
export function findJobRowByKey(db: DatabaseSync, key: string): (JobRow & { input: string }) | undefined {
  return db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`).get(key) as (JobRow & { input: string }) | undefined;
}

export function listJobs(db: DatabaseSync): Job[] {
  const rows = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[];
  return rows.map(toJob);
}

/**
 * Atomically moves the oldest due queued job to `running` and counts the new attempt.
 * Returns undefined when nothing is due.
 */
export function claimNextJob(db: DatabaseSync, now: number): JobRow | undefined {
  return db
    .prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ?
       WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1)
       RETURNING ${JOB_COLUMNS}`,
    )
    .get(new Date(now).toISOString(), now) as JobRow | undefined;
}

