import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  HEARTBEAT_INTERVAL_MS,
  MAX_ATTEMPTS,
  RETRY_MAX_MS,
  RETRY_MIN_MS,
  STEP_MS,
  claimNextJob,
  type JobRow,
} from './jobs.ts';

const IDLE_POLL_MS = 200;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function beat(): void {
  try {
    db.prepare(
      `INSERT INTO heartbeat (name, ts) VALUES ('worker', ?)
       ON CONFLICT (name) DO UPDATE SET ts = excluded.ts`,
    ).run(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}

/** A job left `running` by a worker that died is due again. Only one worker runs at a time. */
function requeueInterrupted(): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`,
  ).run(new Date().toISOString());
}

function setProgress(id: string, completed: number): void {
  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?').run(completed, new Date().toISOString(), id);
}

function finish(job: JobRow): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

function fail(id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', completed = 0, result_output = NULL, error = 'transient failure', updated_at = ? WHERE id = ?`,
  ).run(new Date().toISOString(), id);
}

function scheduleRetry(id: string): void {
  const delay = RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS + 1));
  const now = Date.now();
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ?`,
  ).run(now + delay, new Date(now).toISOString(), id);
}

/** Puts an in-flight job back in the queue when the worker is asked to stop. */
function requeueForShutdown(id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, available_at = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(new Date().toISOString(), id);
}

/** Runs one attempt of a claimed job. `job.attempts` already counts this attempt. */
async function processAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (job.attempts >= MAX_ATTEMPTS) fail(job.id);
    else scheduleRetry(job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    if (stopping) {
      requeueForShutdown(job.id);
      return;
    }
    await sleep(STEP_MS);
    setProgress(job.id, step);
  }
  finish(job);
}

async function main(): Promise<void> {
  requeueInterrupted();
  beat();
  const heartbeat = setInterval(beat, HEARTBEAT_INTERVAL_MS);

  console.log('worker started');
  while (!stopping) {
    try {
      const job = claimNextJob(db, Date.now());
      if (job) await processAttempt(job);
      else await sleep(IDLE_POLL_MS);
    } catch (e) {
      console.error('worker error:', e);
      await sleep(IDLE_POLL_MS);
    }
  }

  clearInterval(heartbeat);
  try {
    db.prepare(`DELETE FROM heartbeat WHERE name = 'worker'`).run();
  } catch {
    // The row only feeds /health; a stale row ages out after 3 seconds anyway.
  }
  db.close();
  console.log('worker stopped');
}

await main();

